scwin.onpageunload = function() {};
scwin.treeviewFormatter = function(value, formattedValue, row, col) {
    //        debugger;
    return value + " Scope formatter";
};
scwin.trigger1_onclick = function(e) {
    var columnInfo = {
        "label": "label",
        "value": "value",
        "depth": "depth",
        "check": "check"
    };
    treeview1.setNodeSet("data:dataList1", columnInfo);
};
scwin.trigger2_onclick = function(e) {
    var columnInfo = {
        "label": "label2",
        "value": "value2",
        "depth": "depth2",
        "check": "check2"
    };
    treeview1.setNodeSet("data:dataList2", columnInfo);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'treeview1').childNodes.length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
